 ## Unreleased

+- Reject invalid items and normalize fields in `addItem`.
 - Faster tag lookup.

 ## 1.4.2 - 2026-09-30
diff --git a/src/items.js b/src/items.js
index b1cae5b..e4746c4 100644
--- a/src/items.js
+++ b/src/items.js
@@ -8,8 +8,34 @@ export async function findByTag(tag) {

 /** Adds an item with the next free id. */
 export async function addItem(item) {
-  if (!item.name) throw new Error("Item needs a name.");
+  if (!item || typeof item !== "object") throw new Error("Invalid item.");
+  if (typeof item.name !== "string" || !item.name.trim()) {
+    throw new Error("Item needs a name.");
+  }
+  if (typeof item.qty !== "number" || !Number.isInteger(item.qty) || item.qty < 0) {
+    throw new Error("Invalid quantity.");
+  }
+  const unit = item.unit === undefined ? "" : item.unit;
+  if (typeof unit !== "string" || /\s/.test(unit)) {
+    throw new Error("Invalid unit.");
+  }
+  if (item.tags !== undefined) {
+    if (!Array.isArray(item.tags) || item.tags.some((t) => typeof t !== "string" || !t.trim())) {
+      throw new Error("Invalid tags.");
+    }
+  }
+  if (item.expires !== undefined) {
+    if (typeof item.expires !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(item.expires)) {
+      throw new Error("Invalid expiry date.");
+    }
+    const d = new Date(`${item.expires}T00:00:00Z`);
+    if (Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== item.expires) {
+      throw new Error("Invalid expiry date.");
+    }
+  }
+  const name = item.name.trim().toLowerCase();
+  const tags = [...new Set((item.tags ?? []).map((t) => t.trim().toLowerCase()))].sort();
   const items = await fetchItems();
   const id = Math.max(0, ...items.map((i) => i.id)) + 1;
-  return saveItem({ tags: [], unit: "", ...item, id });
+  return saveItem({ ...item, id, name, unit, tags });
 }
